import json
import os

from ament_index_python.packages import get_package_prefix
from launch import LaunchDescription
from launch.actions import DeclareLaunchArgument, OpaqueFunction
from launch.substitutions import LaunchConfiguration
from launch_ros.actions import Node

# Mach-E gain tables + vehicle params, regenerated by
# .claude/skills/preview-gain-calibration/scripts/update_from_drive.py after each calibration drive.
GAIN_DIR = os.path.join(os.environ["HOME"], "autoware/src/mcity/preview_control/data/gain/mache")


def launch_setup(context):
    variant = LaunchConfiguration("gain_variant").perform(context)
    if variant not in ("withdelay", "withoutdelay"):
        raise RuntimeError(f"gain_variant must be withdelay or withoutdelay, got {variant!r}")
    with open(os.path.join(GAIN_DIR, "params.json")) as f:
        steering_ratio = float(json.load(f)["steering_ratio"])

    return [
        Node(
            package="preview_control",
            namespace="/mcity",
            executable="preview_control",
            # ~/mcity_demos installs another libpreview_control_component.so that comes first on
            # LD_LIBRARY_PATH; load this package's build instead
            additional_env={"LD_LIBRARY_PATH": os.pathsep.join(
                [os.path.join(get_package_prefix("preview_control"), "lib"), os.environ.get("LD_LIBRARY_PATH", "")])},
            parameters=[
                {"gain_folder": os.path.join(GAIN_DIR, variant) + "/"},
                # withdelay tables need the delay buffer + measured steering feedback
                {"consider_delay_lag": variant == "withdelay"},
                {"steering_ratio": steering_ratio},
                {"slope_folder": LaunchConfiguration("slope_file").perform(context)},
                {"max_ey": 1.5},
                {"max_ephi": 1.0},
                {"max_curvature": 0.2},
                {"speed_ctrl_kp": 1.8},
                {"speed_ctrl_ki": 0.6},
                # -0.03 was the MKZ antenna/CoM heading bias; 0.0 matches stanley_control on the MachE
                {"heading_offset": 0.0},
                {"heading_lookahead_points": 10},
                {"lateral_offset": 0.0},
                # path resampled every 0.04 s of travel = the gain tables' time step
                {"preview_time": 5.0},
                {"desired_time_resolution": 0.04},
                {"trajectory_abort_size": 20},
                {"trajectory_loose_abort_size": 20},
            ],
        ),
    ]


def generate_launch_description():
    return LaunchDescription(
        [
            DeclareLaunchArgument("gain_variant", default_value="withdelay",
                                  description="withdelay | withoutdelay (data/gain/mache/<variant>/)"),
            DeclareLaunchArgument("slope_file", default_value="",
                                  description="road-grade map, e.g. .../data/slope/DIT.txt; empty = flat"),
            OpaqueFunction(function=launch_setup),
        ]
    )
